function fruitPrices() {
  const prices = new Map();
  prices.set("apple", 3);              // put: add a key with its value
  prices.set("pear", 5);
  prices.set("apple", 7);              // the same key again: its value is overwritten
  const a = prices.get("apple");       // get: 7
  const k = prices.has("kiwi");        // contains: false
  prices.delete("pear");               // remove
  return [a, k, prices.size];          // [7, false, 1]
}

List<Object> fruitPrices() {
    Map<String, Integer> prices = new HashMap<>();
    prices.put("apple", 3);                      // put: add a key with its value
    prices.put("pear", 5);
    prices.put("apple", 7);                      // the same key again: its value is overwritten
    int a = prices.get("apple");                 // get: 7
    boolean k = prices.containsKey("kiwi");      // contains: false
    prices.remove("pear");                       // remove
    return List.of(a, k, prices.size());         // [7, false, 1]
}

tuple<int, bool, int> fruitPrices() {
    unordered_map<string, int> prices;
    prices["apple"] = 3;                         // put: add a key with its value
    prices["pear"] = 5;
    prices["apple"] = 7;                         // the same key again: its value is overwritten
    int a = prices["apple"];                     // get: 7
    bool k = prices.count("kiwi") > 0;           // contains: false
    prices.erase("pear");                        // remove
    return {a, k, (int)prices.size()};           // {7, false, 1}
}
